DECLARE
  d jsonb := $rt$[{"kind":"lunch","title":"كبسة لحم بالطريقة الخفيفة","method":"المكونات:\n• 120غ لحم غنم بدون دهن ظاهر (وزنه بعد الطبخ)\n• 150غ رز أبيض مطبوخ\n• 60غ طماطم مفرومة\n• 40غ جزر مبشور\n• 30غ بصل\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• بهارات الكبسة، لومي، هيل، قرنفل، ملح\n\nالطريقة:\n1. نشيل الدهن الظاهر من اللحم ونسلقه بماء مع اللومي والهيل والقرنفل لين يستوي، ونحتفظ بالمرق.\n2. بقدر نسخّن زيت الزيتون ونحمّر البصل، ونضيف الطماطم والجزر وبهارات الكبسة.\n3. نضيف المرق والرز المغسول ونتركه على نار هادية لين ينضج.\n4. نقدّم الرز بالصحن واللحم فوقه، ونقدر نحمّر اللحم بالفرن 10 دقايق قبل التقديم.\n\nالألياف: 3غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"كبسة لحم بالطريقة الخفيفة","portion":"وجبة كاملة","protein":39.1,"carbs":51.3,"fat":17.1}]},{"kind":"lunch","title":"مندي دجاج مع سلطة","method":"المكونات:\n• 150غ فخذ دجاج بدون جلد (وزنه بعد الطبخ)\n• 150غ رز أبيض مطبوخ\n• 30غ بصل\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• سلطة: 60غ خيار و60غ طماطم\n• بهارات المندي، هيل، لومي، ملح\n\nالطريقة:\n1. نتبّل الدجاج ببهارات المندي والملح ونتركه ساعة.\n2. نشوي الدجاج بالفرن على حرارة 200° لين ينضج ويتحمّر (35–40 دقيقة).\n3. نحمّر البصل بزيت الزيتون ونضيف الرز والهيل واللومي والماء، ونطبخه لين ينضج.\n4. نقدّم الدجاج فوق الرز مع السلطة.\n\nالألياف: 2.1غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"مندي دجاج مع سلطة","portion":"وجبة كاملة","protein":42.5,"carbs":49.6,"fat":18}]},{"kind":"lunch","title":"مقلوبة دجاج بالباذنجان المشوي","method":"المكونات:\n• 130غ صدر دجاج (وزنه بعد الطبخ)\n• 150غ رز أبيض مطبوخ\n• 100غ باذنجان مشوي بالفرن (بدل المقلي)\n• 60غ طماطم شرائح\n• 30غ بصل\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• 100غ زبادي قليل الدسم للتقديم\n• بهارات مشكلة، كركم، ملح\n\nالطريقة:\n1. نقطّع الباذنجان شرائح ونرشّه بقليل من الزيت ونشويه بالفرن لين يتحمّر بدل القلي.\n2. نسلق الدجاج مع البصل والبهارات ونحتفظ بالمرق.\n3. بالقدر نرتّب الطماطم ثم الباذنجان ثم الدجاج ثم الرز المغسول، ونضيف المرق لين يغطي الرز.\n4. نطبخها على نار هادية لين ينضج الرز، ثم نقلبها بالصحن ونقدّمها مع الزبادي.\n\nالألياف: 4.3غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"مقلوبة دجاج بالباذنجان المشوي","portion":"وجبة كاملة","protein":51.3,"carbs":63.1,"fat":12.1}]},{"kind":"lunch","title":"برياني دجاج خفيف","method":"المكونات:\n• 140غ صدر دجاج (وزنه بعد الطبخ)\n• 150غ رز بسمتي مطبوخ\n• 50غ زبادي قليل الدسم للتتبيلة\n• 40غ بصل\n• 50غ طماطم\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• بهارات البرياني، زنجبيل، ثوم، كزبرة، ملح\n\nالطريقة:\n1. نتبّل الدجاج بالزبادي وبهارات البرياني والزنجبيل والثوم ونتركه ساعة.\n2. نحمّر البصل بزيت الزيتون لين يذبل، ونضيف الطماطم والدجاج ونطبخه لين ينضج.\n3. نسلق الرز لين ينضج تقريباً ونصفّيه.\n4. نرتّب الرز فوق الدجاج، ونغطيه ونتركه على نار هادية 10 دقايق، ونزيّنه بالكزبرة.\n\nالألياف: 1.9غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"برياني دجاج خفيف","portion":"وجبة كاملة","protein":51,"carbs":51.5,"fat":11.4}]},{"kind":"lunch","title":"مسقعة باذنجان باللحم المفروم مع رز","method":"المكونات:\n• 100غ لحم مفروم قليل الدهن 90% (وزنه بعد الطبخ)\n• 150غ باذنجان مشوي بالفرن\n• 100غ طماطم مفرومة\n• 40غ بصل\n• 50غ فلفل رومي\n• 120غ رز أبيض مطبوخ\n• ثوم، بهارات، ملح\n\nالطريقة:\n1. نشوي الباذنجان مكعبات بالفرن لين يتحمّر (بدون قلي).\n2. نحمّر اللحم المفروم مع البصل والثوم بدون زيت إضافي.\n3. نضيف الفلفل والطماطم والبهارات والباذنجان ونص كوب ماء، ونتركه على نار هادية 15 دقيقة.\n4. نقدّمها مع الرز.\n\nالألياف: 7.2غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"مسقعة باذنجان باللحم المفروم مع رز","portion":"وجبة كاملة","protein":32.4,"carbs":57.5,"fat":12.9}]},{"kind":"lunch","title":"محشي كوسا باللحم والرز","method":"المكونات:\n• 200غ كوسا محفورة\n• 100غ رز (وزنه بعد الطبخ)\n• 80غ لحم مفروم قليل الدهن 90% (وزنه بعد الطبخ)\n• 80غ طماطم (للحشوة والصلصة)\n• 30غ بصل\n• نعناع يابس، بهارات، ثوم، ليمون، ملح\n\nالطريقة:\n1. نخلط الرز المغسول مع اللحم المفروم والبصل المفروم ونص الطماطم والبهارات.\n2. نحشي الكوسا بالخليط بدون ما نملأها للآخر.\n3. نرصّها بالقدر ونضيف باقي الطماطم المهروسة والثوم والنعناع وماء يغطيها.\n4. نطبخها على نار هادية 40 دقيقة لين ينضج الرز، ونعصر عليها ليمون.\n\nالألياف: 3.9غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"محشي كوسا باللحم والرز","portion":"وجبة كاملة","protein":26.8,"carbs":39.5,"fat":10.7}]},{"kind":"lunch","title":"سليق دجاج بالحليب قليل الدسم","method":"المكونات:\n• 130غ صدر دجاج (وزنه بعد الطبخ)\n• 180غ رز أبيض مطبوخ (رز مصري قصير)\n• 150مل حليب قليل الدسم 1%\n• 1 ملعقة صغيرة زبدة (5غ)\n• هيل، مستكة، ورق غار، ملح\n\nالطريقة:\n1. نسلق الدجاج مع الهيل والمستكة وورق الغار والملح ونحتفظ بالمرق.\n2. نطبخ الرز بالمرق، ولما يقارب ينضج نضيف الحليب ونحرّك لين يصير كريمي.\n3. نحمّر الدجاج بالفرن أو المقلاة بدون زيت.\n4. نقدّم السليق بالصحن ونحط الزبدة والدجاج فوقه.\n\nالألياف: 0.7غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"سليق دجاج بالحليب قليل الدسم","portion":"وجبة كاملة","protein":50.3,"carbs":58.3,"fat":10.8}]},{"kind":"lunch","title":"صحن شاورما دجاج بخبز البر","method":"المكونات:\n• 150غ صدر دجاج (وزنه بعد الطبخ)\n• 60غ خبز عربي بر (رغيف صغير)\n• 60غ خيار\n• 60غ طماطم\n• 30غ خس\n• 60غ زبادي قليل الدسم مع ثوم (بدل الثومية)\n• بهارات الشاورما، خل، ليمون، ملح\n\nالطريقة:\n1. نقطّع الدجاج شرائح ونتبّله ببهارات الشاورما والخل والليمون ساعتين.\n2. نشويه بالمقلاة أو الفرن لين يتحمّر.\n3. نخلط الزبادي مع الثوم المهروس والملح بدل الثومية.\n4. نقدّمه بالصحن مع الخضار والخبز، أو نلفّه بالخبز.\n\nالألياف: 5.3غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"صحن شاورما دجاج بخبز البر","portion":"وجبة كاملة","protein":56.9,"carbs":43.2,"fat":7.7}]},{"kind":"lunch","title":"سلطة فتوش بالدجاج المشوي","method":"المكونات:\n• 120غ صدر دجاج مشوي\n• 80غ خس\n• 80غ طماطم\n• 80غ خيار\n• 40غ فلفل رومي\n• 30غ خبز عربي بر محمّص بالفرن\n• 2 ملعقة صغيرة زيت زيتون (10غ)\n• 30غ حب رمان\n• دبس رمان، سماق، نعناع، ليمون، ملح\n\nالطريقة:\n1. نقطّع الخبز مربعات ونحمّصه بالفرن لين يقرمش (بدون قلي).\n2. نقطّع الخضار ونخلطها مع النعناع.\n3. نسوي الصوص: زيت الزيتون مع الليمون ودبس الرمان والسماق والملح.\n4. نضيف الدجاج شرائح والخبز والرمان، ونصب الصوص قبل التقديم.\n\nالألياف: 6.9غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"سلطة فتوش بالدجاج المشوي","portion":"وجبة كاملة","protein":43.3,"carbs":33.4,"fat":15.8}]},{"kind":"breakfast","title":"فتة حمص بالزبادي","method":"المكونات:\n• 120غ حمص مسلوق\n• 150غ زبادي قليل الدسم\n• 40غ خبز عربي بر محمّص بالفرن\n• 2 ملعقة صغيرة طحينة (10غ)\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• ثوم، كمون، ليمون، بابريكا، ملح\n\nالطريقة:\n1. نحمّص الخبز مربعات بالفرن ونرصّه بقاع الصحن.\n2. نسخّن الحمص بقليل من مايته مع الكمون ونوزّعه فوق الخبز.\n3. نخلط الزبادي مع الطحينة والثوم والليمون والملح ونصبّه فوق الحمص.\n4. نرش البابريكا وزيت الزيتون ونقدّمها.\n\nالألياف: 12.5غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"فتة حمص بالزبادي","portion":"وجبة كاملة","protein":24.2,"carbs":67.9,"fat":16.6}]},{"kind":"breakfast","title":"بيض بالطماطم مع خبز البر","method":"المكونات:\n• 3 بيضات (150غ)\n• 150غ طماطم مفرومة\n• 40غ بصل\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• 50غ خبز عربي بر\n• كمون، فلفل أسود، ملح\n\nالطريقة:\n1. نحمّر البصل بزيت الزيتون لين يذبل.\n2. نضيف الطماطم والبهارات ونتركها تتسبك 5 دقايق.\n3. نضيف البيض ونحرّك لين يستوي على كيفك.\n4. نقدّمه مع خبز البر.\n\nالألياف: 5.5غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"بيض بالطماطم مع خبز البر","portion":"وجبة كاملة","protein":25.6,"carbs":38.6,"fat":20.4}]},{"kind":"breakfast","title":"معصوب بالموز (نسخة خفيفة)","method":"المكونات:\n• 60غ خبز عربي بر\n• 100غ موز (حبة متوسطة)\n• 2 ملعقة صغيرة عسل (10غ)\n• 100غ زبادي يوناني قليل الدسم (بدل القشطة)\n• هيل مطحون\n\nالطريقة:\n1. نفتّت الخبز قطع صغيرة ونسخّنه بالمقلاة.\n2. نهرس الموز ونخلطه مع الخبز لين يتماسك.\n3. نوزّعه بالصحن ونحط فوقه الزبادي اليوناني.\n4. نرش العسل والهيل ونقدّمه.\n\nالألياف: 6.3غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"معصوب بالموز (نسخة خفيفة)","portion":"وجبة كاملة","protein":17,"carbs":68.5,"fat":3.2}]},{"kind":"snack","title":"تمر بالطحينة واللوز","method":"المكونات:\n• 2 حبة تمر مجدول (48غ)\n• 2 ملعقة صغيرة طحينة (10غ)\n• 10غ لوز (7 حبات تقريباً)\n\nالطريقة:\n1. نشق التمر ونشيل النوى.\n2. نحشي كل حبة بالطحينة واللوز.\n3. نقدّمه سناك قبل التمرين أو مع القهوة.\n\nالألياف: 5.4غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"تمر بالطحينة واللوز","portion":"وجبة كاملة","protein":4.7,"carbs":40.3,"fat":10.5}]}]$rt$;
  m jsonb; it jsonb; v_plan uuid; v_meal uuid; j int; k int;
BEGIN
  SELECT id INTO v_plan FROM nutrition_plans WHERE order_id IS NULL AND is_library;
  IF v_plan IS NULL THEN RAISE EXCEPTION 'مكتبة الوجبات غير موجودة. شغّلي ملف meal-library أولاً.'; END IF;
  j := coalesce((SELECT max(position) + 1 FROM plan_meals WHERE plan_id = v_plan), 0);
  FOR m IN SELECT * FROM jsonb_array_elements(d) LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM plan_meals WHERE plan_id = v_plan AND title = m->>'title');
    INSERT INTO plan_meals (plan_id, kind, title, method, position) VALUES (v_plan, m->>'kind', m->>'title', nullif(m->>'method', ''), j) RETURNING id INTO v_meal;
    k := 0;
    FOR it IN SELECT * FROM jsonb_array_elements(m->'items') LOOP
      INSERT INTO plan_items (meal_id, food, portion, protein, carbs, fat, position)
      VALUES (v_meal, it->>'food', nullif(it->>'portion', ''), (it->>'protein')::numeric, (it->>'carbs')::numeric, (it->>'fat')::numeric, k);
      k := k + 1;
    END LOOP;
    j := j + 1;
  END LOOP;
  UPDATE nutrition_plans SET notes = regexp_replace(coalesce(notes, ''), '[0-9]+ وجبة', (SELECT count(*) FROM plan_meals WHERE plan_id = v_plan) || ' وجبة'), updated_at = now() WHERE id = v_plan;
END $do$;

DO $do$
DECLARE
  d jsonb := $rt$[{"kind":"breakfast","title":"كلوب ساندوتش البيض والتيركي","method":"المكونات:\n• 58غ توست (3 شرائح)\n• 2 بيضة كاملة + 2 بياض بيض\n• 50غ شرائح تيركي (ديك رومي)\n• 25غ جبن قشقوان\n• 19غ جبن شرائح\n• 36غ طماطم شرائح\n• 15غ مايونيز\n• 11غ صلصة رانش\n• خس\n\nالطريقة:\n1. نحمّص التوست، ونطبخ البيض بالمقلاة كعجة رقيقة.\n2. الطبقة الأولى: توست مدهون بالمايونيز ثم خس وبيض وجبن قشقوان.\n3. الطبقة الثانية: توست ثم تيركي وطماطم وجبن شرائح.\n4. نقفلها بآخر توستة مدهونة بالرانش، ونقطعها مثلثات.\n\nالألياف: 2غ\n\nملاحظة: محسوبة بمايونيز ورانش وجبن عاديين؛ لو استخدمتي النسخ الخفيفة تقل الدهون والسعرات. قشقوان محسوب ببديله الأقرب في USDA (بروفولون). البطاطس الجانبية غير محسوبة. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"كلوب ساندوتش البيض والتيركي","portion":"ساندوتش كامل","protein":50.5,"carbs":33.4,"fat":41.3}]},{"kind":"lunch","title":"دجاج ماسالا بالزبادي مع رز","method":"المكونات:\n• 373غ صدر دجاج فيليه (نيء) — للحصتين\n• 72غ بصل\n• 9غ ثوم\n• 150غ زبادي يوناني (نصه للتتبيلة ونصه لسلطة الخيار)\n• 17غ صلصة/معجون طماطم\n• 75غ كريمة طبخ\n• 80غ رز قبل الطبخ\n• بهارات: زنجبيل، ثوم وبصل بودرة، بهارات دجاج وهندية، كاري، كركم، زعفران، فلفل مجروش، ملح\n\nالطريقة:\n1. نتبّل الدجاج بنص الزبادي اليوناني والبهارات ونتركه نص ساعة.\n2. على صاج حار وبدون زيت نحمّر الثوم والبصل لين يذبلون.\n3. نضيف الدجاج بتتبيلته ونقلّبه لين يستوي، وآخر شيء نضيف صلصة الطماطم وكريمة الطبخ.\n4. نغسل الرز كويس وننقعه 10 دقايق قبل الطبخ عشان يطلع منثور.\n5. سلطة جانبية: باقي الزبادي مع خيار مبشور مصفّى وملح وليمون.\n\nالألياف: 1.6غ\n\nملاحظة: صلصة الطماطم محسوبة كمعجون طماطم (17غ). الخيار غير محسوب. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"دجاج ماسالا بالزبادي مع رز","portion":"حصة (الوصفة لحصتين)","protein":54.5,"carbs":42.8,"fat":13.8}]},{"kind":"breakfast","title":"عريكة جنوبية صحية","method":"المكونات:\n• 40غ دقيق بر (أسمر)\n• 4غ زبدة\n• 55غ تمر (خلاص)\n• 150مل ماء حار\n• هيل وزنجبيل مطحون وذرة ملح\n• سكر ستيفيا (اختياري)\n\nالطريقة:\n1. نحمّص الدقيق على النار لين يتغير لونه.\n2. ننقع 40غ من التمر بالماء الحار، ونسخّنه دقيقة بالمايكرويف ونهرسه.\n3. نضيف التمر للدقيق على الصاج ونعصده مع الهيل والزنجبيل والملح لين يتماسك.\n4. نصبّه بالصحن ونحط الزبدة الذايبة بالوسط، ونزيّنه بباقي التمر.\n\nالألياف: 8.7غ\n\nملاحظة: تمر الخلاص محسوب بقيم تمر دقلة نور (الأقرب في USDA). القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"عريكة جنوبية صحية","portion":"صحن","protein":6.7,"carbs":70.1,"fat":4.5}]},{"kind":"lunch","title":"برجر المطاعم بطريقة صحية مع بطاطس","method":"المكونات:\n• 232غ لحم مفروم (نيء)\n• 239غ بطاطس\n• 51غ خبز بريوش\n• 40غ جبن شرائح\n• 24غ طماطم\n• الصوص: 100غ زبادي يوناني + 16غ كاتشب + 16غ خردل + 16غ مايو\n• خس ومخلل\n• فلفل أسود، ملح، بابريكا، ثوم وبصل بودرة، بهارات إيطالية، كيجن، ماء المخلل\n\nالطريقة:\n1. نبهّر اللحم بالملح والفلفل الأسود، ونشكّله أقراص.\n2. نشويه على صاج حار جداً من الجهتين، ونحط عليه الجبن آخر دقيقة لين يذوب.\n3. نخلط مكونات الصوص مع البهارات وماء المخلل.\n4. نقطّع البطاطس ونبهّرها بنفس البهارات، ونطبخها بالقلاية الهوائية حوالي 20 دقيقة.\n5. نركّب: خبز، صوص، خس، لحم بالجبن، مخلل، طماطم، صوص، ونقفل.\n\nالألياف: 7.2غ\n\nملاحظة: اللحم محسوب كمفروم بقري 90% (المنشور ما حدد نسبة الدهن)، والبريوش بقيم خبز البيض في USDA. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"برجر المطاعم بطريقة صحية مع بطاطس","portion":"وجبة كاملة","protein":74.6,"carbs":78.4,"fat":53.3}]},{"kind":"lunch","title":"فوتشيني دجاج بالكريمة الخفيفة","method":"المكونات:\n• 297غ صدر دجاج (نيء)\n• 60غ فوتشيني قبل الطبخ\n• 66غ جبن فيلادلفيا لايت\n• 6غ ثوم\n• فلفل أسود، ثوم وبصل بودرة، ملح، فلفل مجروش، بهارات إيطالية\n\nالطريقة:\n1. نبهّر الدجاج ونشويه على الصاج من الجهتين، ونرفعه.\n2. بنفس الصاج نحمّر الثوم، ونضيف جبن الفيلادلفيا وشوي من مويا سلق المكرونة لين يصير صوص كريمي.\n3. نخلط المكرونة بالصوص.\n4. نقطّع الدجاج بعد ما يبرد شوي ونحطه فوق، مع فلفل مجروش وبهارات إيطالية.\n\nالألياف: 2غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"فوتشيني دجاج بالكريمة الخفيفة","portion":"وجبة كاملة","protein":80.2,"carbs":51.2,"fat":19.7}]},{"kind":"lunch","title":"باستا بارميزان بينك بالدجاج المشوي","method":"المكونات:\n• 65غ باستا قبل الطبخ\n• 5غ ثوم\n• 37غ طماطم مهروسة\n• 17غ بارميزان\n• 15غ موزاريلا\n• 50غ جبن فيلادلفيا لايت\n• 298غ صدر دجاج (نيء)\n• ثوم وبصل بودرة، بابريكا، ملح، فلفل أسود ومجروش، بهارات دجاج\n\nالطريقة:\n1. نضرب الدجاج لين يصير رقيق ونبهّره، ونشويه على صاج أو شواية حارة 15 دقيقة كحد أقصى حسب سماكته، ونتركه يبرد قبل التقطيع.\n2. نحمّر الثوم المهروس، ونضيف الطماطم ومويا الباستا وجبن الفيلادلفيا ونتركها تتسبك.\n3. نضيف الباستا والبارميزان والموزاريلا ونقلّب.\n4. نقدّمها مع الدجاج ورشة بارميزان.\n\nالألياف: 2.6غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"باستا بارميزان بينك بالدجاج المشوي","portion":"وجبة كاملة","protein":88.6,"carbs":57.8,"fat":24.3}]},{"kind":"snack","title":"بودنق الحليب المحموس بالشوكولاتة","method":"المكونات:\n• الكيك: 30غ شوفان مطحون، 7غ كاكاو، 5غ باكنج باودر، 10غ بروتين باودر، بيضة (52غ)، 32غ زبادي يوناني، سكر نولا، 20مل ماء\n• الطبقة الثانية: 12غ دريم ويب، 72غ فيلادلفيا لايت، سكر نولا، 14غ حليب بودرة محموس\n• الطبقة الثالثة: 27غ بسكويت مطحون\n• الطبقة الرابعة: 40غ شوكولاتة بالحليب\n\nالطريقة:\n1. نحمّس حليب البودرة على النار لين يصير ذهبي.\n2. نخلط مكونات الكيك ونخبزه بفرن مسبق التسخين 12 دقيقة (10 من تحت ودقيقتين من فوق).\n3. نخفق الدريم ويب مع جبن الفيلادلفيا والسكر والحليب المحموس ونوزّعه فوق الكيك.\n4. نرش البسكويت المطحون، ثم الشوكولاتة الذايبة، ونقسمه 4 حصص.\n\nالألياف: 2غ\n\nملاحظة: الكميات للصينية كاملة (4 حصص) والقيم للحصة. البسكويت والشوكولاتة والدريم ويب محسوبة ببدائل عامة من USDA. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"بودنق الحليب المحموس بالشوكولاتة","portion":"حصة (من 4 حصص)","protein":9.3,"carbs":23.4,"fat":10.1}]},{"kind":"snack","title":"سوفلية الشوكولاتة السريعة","method":"المكونات:\n• 100مل حليب بروتين ندى\n• 56غ بسكويت بدون كريمة\n• 2غ باكنج باودر\n• 30مل ماء\n\nالطريقة:\n1. نخلط كل المكونات بالخلاط مع الماء.\n2. نوزّعها على كاستين صغار.\n3. نطبخها بالقلاية الهوائية 6 دقايق على 180°.\n\nالألياف: 1غ\n\nملاحظة: بسكويت جالون محسوب ببديل عام (بسكويت سادة) من USDA. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"سوفلية الشوكولاتة السريعة","portion":"حصة (الوصفة لحصتين)","protein":6.1,"carbs":26.3,"fat":3}]},{"kind":"snack","title":"سكوب كوكيز بالشوكولاتة","method":"المكونات:\n• 93غ زبدة بحرارة الغرفة\n• 130غ دقيق\n• 100غ شوكولاتة (12.5غ لكل حبة)\n• بيضة (52غ)\n• 2غ باكنج باودر + 2غ بيكربونات الصوديوم\n• 3غ نشا ذرة\n• 120غ محلي إرثيتول\n• 5غ دبس تمر، 5غ فانيلا سائلة\n\nالطريقة:\n1. نخلط الزبدة مع المحلي لين يتجانس، ثم البيض والفانيلا ودبس التمر.\n2. نضيف المواد الجافة: الدقيق والنشا والبيكربونات والباكنج باودر.\n3. نقسم العجينة على 8 كرات ونحشي كل وحدة بالشوكولاتة، وندخلها الفريزر ساعتين على الأقل.\n4. نخبزها بالقلاية الهوائية مسبقة التسخين على 175° لمدة 8 دقايق، ونتركها تبرد بمكانها قبل ما نشيلها.\n\nالألياف: 0.9غ\n\nملاحظة: القيم للحبة الواحدة. الإرثيتول ودبس التمر والفانيلا غير محسوبة (كميات قليلة أو خالية من السعرات)، والشوكولاتة بقيم الشوكولاتة بالحليب. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"سكوب كوكيز بالشوكولاتة","portion":"حبة (من 8)","protein":3.6,"carbs":20.4,"fat":13.9}]},{"kind":"breakfast","title":"بانكيك الشتاء بالكاكاو والتوت","method":"المكونات:\n• 35غ شوفان مطحون\n• بيضة (54غ)\n• 15غ بروتين باودر\n• 5غ باكنج باودر\n• 5غ كاكاو\n• 82غ زبادي يوناني\n• 12غ كندر أصابع للتزيين\n• 38غ توت أزرق\n• سكر ستيفيا، ذرة ملح، 15مل ماء، قهوة (اختياري)\n\nالطريقة:\n1. نخلط البيض والزبادي اليوناني كويس.\n2. نضيف الشوفان والكاكاو والباكنج والبروتين والملح والستيفيا والماء.\n3. نصبّها على صاج بأشكال صغيرة ونقلبها لما تطلع فقاعات.\n4. نزيّنها بالكندر الذايب والتوت.\n\nالألياف: 6.7غ\n\nملاحظة: الكندر محسوب بقيم الشوكولاتة بالحليب. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"بانكيك الشتاء بالكاكاو والتوت","portion":"صحن","protein":30.5,"carbs":48.4,"fat":13.5}]},{"kind":"snack","title":"فانيلا لاتيه بدون سكر","method":"المكونات:\n• 150مل حليب خالي الدسم (خالي اللاكتوز إذا تبغين)\n• 6غ قهوة سريعة التحضير + 40مل ماء دافي\n• سيرب فانيلا خالي السعرات (أو ستيفيا مع فانيلا)\n• ثلج\n\nالطريقة:\n1. نذوّب القهوة بالماء الدافي.\n2. نحط الثلج والحليب والسيرب بالكاس.\n3. نصب القهوة فوقها ونحرّك.\n\nالألياف: 0غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"فانيلا لاتيه بدون سكر","portion":"كوب","protein":5.8,"carbs":12,"fat":0.2}]},{"kind":"breakfast","title":"فرنش توست بريوش بالآيسكريم","method":"المكونات:\n• 62غ خبز بريوش\n• 60مل حليب بروتين فانيلا ندى\n• بيضة (54غ)\n• 10غ كندر ميلكي\n• 35غ آيسكريم فانيلا\n• قرفة ومحلي فانيلا\n\nالطريقة:\n1. نخفق البيض مع الحليب والقرفة والمحلي.\n2. نغمس البريوش ونشويه على صاج حار من الجهتين.\n3. نحط فوقه الآيسكريم والكندر الذايب.\n\nالألياف: 2غ\n\nملاحظة: الكندر محسوب بقيم الشوكولاتة بالحليب، والبريوش بقيم خبز البيض في USDA. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"فرنش توست بريوش بالآيسكريم","portion":"صحن","protein":20.4,"carbs":51.7,"fat":15.7}]},{"kind":"snack","title":"سناك البروتين بالقلاية الهوائية (زي الهوا)","method":"المكونات:\n• 20غ شوفان مطحون\n• 16غ بروتين باودر\n• 3غ باكنج باودر\n• 10غ حليب بودرة\n• سكر ستيفيا وقرفة\n• 50مل ماء\n• 14غ كندر للتزيين (اختياري)\n\nالطريقة:\n1. نحمّس الحليب البودرة على النار لين يصير ذهبي ونرفعه بسرعة لأنه يحترق.\n2. بصحن نخلط الشوفان والبروتين والباكنج والحليب المحموس والستيفيا والقرفة مع الماء.\n3. نطبخه بالقلاية الهوائية مسبقة التسخين على 170° لمدة 5 دقايق.\n4. نزيّنه بالكندر الذايب.\n\nالألياف: 2.5غ\n\nملاحظة: ما عندك بروتين باودر؟ استخدمي حليب بروتين بدل الماء و30غ شوفان. الكندر محسوب بقيم الشوكولاتة بالحليب. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"سناك البروتين بالقلاية الهوائية (زي الهوا)","portion":"حصة","protein":16.6,"carbs":32.4,"fat":5.7}]},{"kind":"lunch","title":"كبسة لحم صافي سريعة","method":"المكونات:\n• 80غ رز قبل الطبخ — للحصتين\n• 300غ لحم تندرلوين (جاموس أو بقري) خالي الدهن قبل الطبخ — للحصتين\n• بصل\n• بهارات حبوب: كمون، فلفل أسود، قرفة، قرنفل، ورق غار، خردل، يانسون، لومي، ثوم وبصل مجفف، هيل\n• ملح\n\nالطريقة:\n1. نشوّح اللحم لين ياخذ لون، ونضيف البصل والملح والبهارات.\n2. نضيف ماء يغطي اللحم ونتركه نص ساعة على نار هادية.\n3. نصفّي البهارات من المرق، ونحط الرز المنقوع ونقلّل الماء إذا كان كثير.\n4. نتركه ربع ساعة لين ينشف بدون تقليب كثير، ونقدّمه مع سلطة طماطم وخيار ولبن.\n\nالألياف: 0.5غ\n\nملاحظة: لحم الجاموس محسوب بقيم تندرلوين بقري صافي من USDA (ما فيه جاموس في القاعدة). البصل والسلطة غير محسوبة. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"كبسة لحم صافي سريعة","portion":"حصة (الوصفة لحصتين)","protein":36,"carbs":32,"fat":9.1}]},{"kind":"snack","title":"تشيز كيك البيكان","method":"المكونات:\n• 30غ بسكويت سادة بدون سكر\n• 18غ دريم ويب\n• 18غ جبن فيلادلفيا لايت\n• 40مل حليب بروتين ندى سادة\n• 50غ سكر نولا (أو أي محلي خالي السعرات)\n• 18غ بيكان\n• ماء بارد، ذرة ملح\n\nالطريقة:\n1. نطحن البسكويت ونخلطه بـ4مل ماء، ونضغطه بقاع صينية صغيرة ونخبزه 5 دقايق.\n2. نخفق الدريم ويب مع 25مل ماء بارد لين يصير كريمة، ونضيف 15مل ماء ثم جبن الفيلادلفيا، ونوزّعها فوق البسكويت.\n3. نكرمل المحلي، ونضيف حليب البروتين والملح ونحرّك بدون توقف، ثم البيكان.\n4. نصبّ صوص البيكان فوق الكريمة. مهم: كل طبقة تبرد قبل اللي بعدها.\n\nالألياف: 2.7غ\n\nملاحظة: القيم للصينية كاملة. البسكويت محسوب ببديل عام (بسكويت سادة) من USDA، والمحلي غير محسوب. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"تشيز كيك البيكان","portion":"الصينية كاملة (تُقسم حسب الرغبة)","protein":9.4,"carbs":39.9,"fat":26.3}]}]$rt$;
  m jsonb; it jsonb; v_plan uuid; v_meal uuid; j int; k int;
BEGIN
  SELECT id INTO v_plan FROM nutrition_plans WHERE order_id IS NULL AND is_library;
  IF v_plan IS NULL THEN RAISE EXCEPTION 'مكتبة الوجبات غير موجودة. شغّلي ملف meal-library أولاً.'; END IF;
  j := coalesce((SELECT max(position) + 1 FROM plan_meals WHERE plan_id = v_plan), 0);
  FOR m IN SELECT * FROM jsonb_array_elements(d) LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM plan_meals WHERE plan_id = v_plan AND title = m->>'title');
    INSERT INTO plan_meals (plan_id, kind, title, method, position) VALUES (v_plan, m->>'kind', m->>'title', nullif(m->>'method', ''), j) RETURNING id INTO v_meal;
    k := 0;
    FOR it IN SELECT * FROM jsonb_array_elements(m->'items') LOOP
      INSERT INTO plan_items (meal_id, food, portion, protein, carbs, fat, position)
      VALUES (v_meal, it->>'food', nullif(it->>'portion', ''), (it->>'protein')::numeric, (it->>'carbs')::numeric, (it->>'fat')::numeric, k);
      k := k + 1;
    END LOOP;
    j := j + 1;
  END LOOP;
  UPDATE nutrition_plans SET notes = regexp_replace(coalesce(notes, ''), '[0-9]+ وجبة', (SELECT count(*) FROM plan_meals WHERE plan_id = v_plan) || ' وجبة'), updated_at = now() WHERE id = v_plan;
END $do$;

SELECT m.title, round(sum(i.protein*4 + i.carbs*4 + i.fat*9)) AS kcal
  FROM plan_meals m JOIN nutrition_plans p ON p.id = m.plan_id JOIN plan_items i ON i.meal_id = m.id
 WHERE p.is_library AND p.order_id IS NULL AND m.title IN ('كبسة لحم بالطريقة الخفيفة', 'مندي دجاج مع سلطة', 'مقلوبة دجاج بالباذنجان المشوي', 'برياني دجاج خفيف', 'مسقعة باذنجان باللحم المفروم مع رز', 'محشي كوسا باللحم والرز', 'سليق دجاج بالحليب قليل الدسم', 'صحن شاورما دجاج بخبز البر', 'سلطة فتوش بالدجاج المشوي', 'فتة حمص بالزبادي', 'بيض بالطماطم مع خبز البر', 'معصوب بالموز (نسخة خفيفة)', 'تمر بالطحينة واللوز', 'كلوب ساندوتش البيض والتيركي', 'دجاج ماسالا بالزبادي مع رز', 'عريكة جنوبية صحية', 'برجر المطاعم بطريقة صحية مع بطاطس', 'فوتشيني دجاج بالكريمة الخفيفة', 'باستا بارميزان بينك بالدجاج المشوي', 'بودنق الحليب المحموس بالشوكولاتة', 'سوفلية الشوكولاتة السريعة', 'سكوب كوكيز بالشوكولاتة', 'بانكيك الشتاء بالكاكاو والتوت', 'فانيلا لاتيه بدون سكر', 'فرنش توست بريوش بالآيسكريم', 'سناك البروتين بالقلاية الهوائية (زي الهوا)', 'كبسة لحم صافي سريعة', 'تشيز كيك البيكان')
 GROUP BY m.title, m.position ORDER BY m.position;
COMMIT;
